const c = $input.first().json;
const newTotal = (c.total_missions_count || 0) + 1;
const newPresent = (c.present_count || 0) + 1;
const newAbsent = c.absent_count || 0;
const newLate = c.late_count || 0;

const absenceRate = newTotal > 0 ? newAbsent / newTotal : 0;
const lateRate = newTotal > 0 ? newLate / newTotal : 0;
const reliabilityScore = Math.round(
  Math.max(0, Math.min(100,
    100 - (absenceRate * 100 * 2) - (lateRate * 100 * 1) - ((c.no_reply_count || 0) * 3)
  ))
);

return [{ json: {
  ...c,
  outcome: 'PRESENT',
  new_total: newTotal,
  new_present: newPresent,
  new_absent: newAbsent,
  new_late: newLate,
  new_absence_rate: absenceRate,
  new_late_rate: lateRate,
  new_reliability_score: reliabilityScore
}}];

